WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessions_payments AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_burst_tier, session_no, MIN(paid_at) AS first_seen, SUM(CASE WHEN status = 'SUCCESS' THEN is_new_burst ELSE 0 END) AS success_is_new_burst, MAX(paid_at) AS last_seen, SIZE(COLLECT_SET(status)) AS num_status, ROUND(AVG(session_no), 2) AS avg_session_no, COUNT(*) AS num_rows FROM sessions_payments GROUP BY CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END, session_no ORDER BY num_status DESC NULLS LAST
